type Profile = "legacy" | "admin" | "app_manager" | "mechanic" | "maintenance_assistant" | "toolroom" | "commander" | "copilot" | "flight_attendant" | "coordination" | "dispatch" | "maintenance_director" | "maintenance_manager" | "maintenance_coordinator" | "maintenance_leader" | "maintenance_inspector";
type Aircraft = { prefix: string; model: string; base: string; };
type CommentAttachment = RecordMedia;
type Entry = { wallPostId?: string; assignedTo?: string[]; id: string; kind: "action" | "comment" | "link" | "status" | "assignment"; description: string; result?: "satisfactory" | "nonconforming"; employeeNumber: string; at: string; workShift?: string; mission?: string; attachments?: CommentAttachment[]; };
type MaintenancePriority = "routine" | "urgent" | "logged" | "not_logged";
export type MaintenanceRecord = { technicalCase?:TechnicalCase; attachments?:RecordMedia[]; pinnedCommentId?:string; id: string; ticketCode: string; recordType: "fault" | "discrepancy" | "inspection"; base: string; model: string; prefix: string; priority: MaintenancePriority; originShift?: "day" | "night"; originMission?: string; status: "open" | "closed"; title: string; description: string; tc: string; sourceFlightId?: string; assignedTo: string[]; links: string[]; entries: Entry[]; createdBy: string; createdAt: string; updatedAt: string; revision: number; };
type Row = { technical_case?:TechnicalCase; id: string; ticket_code: string | null; record_type: MaintenanceRecord["recordType"]; base: string; model: string; prefix: string; priority: MaintenanceRecord["priority"]; status: MaintenanceRecord["status"]; title: string; tc: string | null; source_flight_id: string | null; created_by: string; created_at: string; updated_at: string; revision: number; data: Partial<MaintenanceRecord>; };

const typeLabel = { fault: "Relato Técnico", discrepancy: "Relato Técnico", inspection: "Inspeção programada" };
const now = () => new Date().toISOString();
const uid = () => crypto.randomUUID();
const dateTime = (value: string) => new Date(value).toLocaleString("pt-BR");
const toRecord = (row: Row): MaintenanceRecord => ({ technicalCase:{...(row.technical_case??legacyTechnicalCase(row.record_type,row.priority)),priority:row.technical_case?.priority??(row.priority==="urgent"?"urgent":"routine")}, attachments:row.data.attachments??[], pinnedCommentId:row.data.pinnedCommentId, id: row.id, ticketCode: row.ticket_code ?? row.data.ticketCode ?? "", recordType: row.record_type, base: row.base, model: row.model, prefix: row.prefix, priority: row.record_type === "fault" && (row.priority === "urgent" || row.priority === "routine") ? "logged" : row.priority, originShift: row.data.originShift, originMission: row.data.originMission, status: row.status, title: row.title, description: row.data.description ?? "", tc: row.tc ?? "", sourceFlightId: row.source_flight_id ?? undefined, assignedTo: row.data.assignedTo ?? [], links: row.data.links ?? [], entries: row.data.entries ?? [], createdBy: row.created_by, createdAt: row.created_at, updatedAt: row.updated_at, revision: row.revision });
const payload = (item: MaintenanceRecord) => ({ ...item });
const needsTechnicalAttention = (item: MaintenanceRecord) => item.recordType!=="inspection" && serviceCasePending(item.technicalCase);

export function MaintenanceRecords({ assignedBase = "", mode, supabase, user, userDirectory, profile, bases, models, aircraft, seed, openRecordId, requireSignature, onOpenTools, onRecordOpened, onSeedConsumed, onError }: { assignedBase?: string; mode: "faults" | "discrepancies" | "service"; supabase: SupabaseClient | null; user: string; userDirectory: UserDirectory; profile: Profile; bases: string[]; models: string[]; aircraft: Aircraft[]; seed?: { type: "fault" | "discrepancy"; prefix: string; sourceFlightId: string; } | null; openRecordId?: string | null; requireSignature: (action: () => void | Promise<void>, label?: string) => Promise<boolean>; onOpenTools?: () => void; onRecordOpened?: () => void; onSeedConsumed?: () => void; onError: (message: string) => void; }) {
  const [records, setRecords] = useState<MaintenanceRecord[]>([]); const [people, setPeople] = useState<Person[]>([]); const [open, setOpen] = useState<MaintenanceRecord | null>(null); const [creating, setCreating] = useState<MaintenanceRecord["recordType"] | null>(seed?.type ?? null); const [directFault,setDirectFault]=useState(false); const [batchCreating, setBatchCreating] = useState(false); const [filters, setFilters] = useState({ base: "", model: "", prefix: "", status: "", priority: "", urgency: "", report: "", aircraftState: "", investigation: "", from:localFilterDay(), until:localFilterDay() });
  const filterDay = useRef(localFilterDay());
  const [today, setToday] = useState(localFilterDay);
  useEffect(() => {
    const refreshDay = () => {
      const next = localFilterDay();
      const previous = filterDay.current;
      if (next === previous) return;
      filterDay.current = next;
      setToday(next);
      setFilters(current => current.from === previous && current.until === previous
        ? { ...current, from: next, until: next } : current);
    };
    const timer = window.setInterval(refreshDay, 60000);
    window.addEventListener("focus", refreshDay);
    document.addEventListener("visibilitychange", refreshDay);
    return () => {
      window.clearInterval(timer);
      window.removeEventListener("focus", refreshDay);
      document.removeEventListener("visibilitychange", refreshDay);
    };
  }, []);
  const [chatCounts,setChatCounts]=useState<Record<string,{message_count:number;unread:number}>>({});
  useEffect(()=>{if(!supabase)return;let active=true;const load=async()=>{const{data,error}=await supabase.rpc('internal_chat',{p_action:'list'});if(!error&&active)setChatCounts((data||[]).reduce((counts:Record<string,{message_count:number;unread:number}>,c:{record_id?:string;message_count:number;unread:number})=>{if(c.record_id){const previous=counts[c.record_id];counts[c.record_id]={message_count:(previous?.message_count||0)+Number(c.message_count),unread:(previous?.unread||0)+Number(c.unread)};}return counts;},{}));};void load();const t=setInterval(()=>void load(),10000);return()=>{active=false;clearInterval(t);};},[supabase,user]);
  const [recordReads,setRecordReads]=useState<Record<string,string>>({});
  const [commentsTarget,setCommentsTarget]=useState<string|null>(null);
  useEffect(()=>{if(!supabase)return;let active=true;const refresh=async()=>{const{data,error}=await supabase.from("technical_comment_reads").select("record_id,seen_at");if(!error&&active)setRecordReads(Object.fromEntries((data||[]).map(r=>[r.record_id,r.seen_at])));};void refresh();const timer=setInterval(()=>void refresh(),15000);return()=>{active=false;clearInterval(timer);};},[supabase,user,open]);
  const leadership = ["admin", "app_manager", "legacy", "maintenance_director", "maintenance_manager", "maintenance_coordinator", "maintenance_leader", "maintenance_inspector"].includes(profile);
  const load = useCallback(async () => { if(!supabase) return; const { data, error } = await supabase.from("maintenance_records").select("*").order("updated_at", { ascending: false }); if(error) { onError(`Registros técnicos indisponíveis: ${error.message}`); return; } const next = ((data ?? []) as Row[]).map(toRecord); setRecords(next); setOpen((current) => current ? next.find((item) => item.id === current.id) ?? current : null); }, [supabase, onError]);
  useEffect(() => { const timer = setTimeout(() => void load(), 0); if(!supabase) return () => clearTimeout(timer); const channel = supabase.channel("maintenance-records-ui").on("postgres_changes", { event: "*", schema: "public", table: "maintenance_records" }, () => void load()).subscribe(); return () => { clearTimeout(timer); void supabase.removeChannel(channel); }; }, [supabase, load]);
  useEffect(() => {
    const refresh = () => { if (document.visibilityState === "visible") void load(); };
    window.addEventListener("focus", refresh);
    window.addEventListener("online", refresh);
    document.addEventListener("visibilitychange", refresh);
    return () => {
      window.removeEventListener("focus", refresh);
      window.removeEventListener("online", refresh);
      document.removeEventListener("visibilitychange", refresh);
    };
  }, [load]);
  useEffect(() => { if(!openRecordId) return; const target = records.find((item) => item.id === openRecordId); if(!target) return; const timer = window.setTimeout(() => { setOpen(target); onRecordOpened?.(); }, 0); return () => window.clearTimeout(timer); }, [openRecordId, records, onRecordOpened]);
  useEffect(() => { if(!supabase) return; void supabase.rpc("get_operational_assignments").then(({ data }) => setPeople(((data ?? []) as { employee_number: string; display_name: string; access_profile: Profile; assigned_base: string | null; fleets: string[]; mission: string | null; work_shift: string | null; }[]).map((p) => ({ employeeNumber: p.employee_number, displayName: p.display_name, profile: p.access_profile, assignedBase: p.assigned_base ?? "", fleets: p.fleets ?? [], mission: p.mission ?? "", workShift: p.work_shift ?? "" })))); }, [supabase]);
  const scoped = useMemo(() => records.filter((item) => (mode === "faults" || mode === "discrepancies") ? item.recordType !== "inspection" : item.recordType === "inspection" || needsTechnicalAttention(item)), [records, mode]);
  const modelOptions = useMemo(() => [...new Set(aircraft.filter((a) => !filters.base || a.base === filters.base).map((a) => a.model))].sort(), [aircraft, filters.base]);
  const prefixOptions = useMemo(() => aircraft.filter((a) => (!filters.base || a.base === filters.base) && (!filters.model || a.model === filters.model)).map((a) => a.prefix).sort(), [aircraft, filters.base, filters.model]);
  const visible = useMemo(() => scoped.filter((item) => ((filters.from===today && filters.until===today && (needsTechnicalAttention(item)||(mode==="service"&&item.recordType==="inspection"&&item.status!=="closed"))) || ((!filters.from || localFilterDay(new Date(item.createdAt))>=filters.from) && (!filters.until || localFilterDay(new Date(item.createdAt))<=filters.until))) && (!filters.base || item.base === filters.base) && (!filters.model || item.model === filters.model) && (!filters.prefix || item.prefix.includes(filters.prefix.toUpperCase())) && (!filters.status || (item.recordType==="inspection"?item.status:item.technicalCase?.investigation==="closed"?"closed":"open") === filters.status) && (!filters.priority || item.technicalCase?.official === filters.priority) && (!filters.urgency || (item.technicalCase?.priority||"routine")===filters.urgency) && (!filters.report || item.technicalCase?.report === filters.report) && (!filters.aircraftState || item.technicalCase?.aircraft === filters.aircraftState) && (!filters.investigation || (filters.investigation==="following" ? ["monitoring","condition_watch"].includes(item.technicalCase?.investigation||"") : item.technicalCase?.investigation === filters.investigation) )).sort((a,b)=>Number(isUrgentTechnical(b.technicalCase))-Number(isUrgentTechnical(a.technicalCase))), [scoped, filters, today, mode]);
  const notificationBase = assignedBase || people.find(person => person.employeeNumber === user)?.assignedBase;
  const notificationRecords = visible.filter(item => ["admin","app_manager","maintenance_director","maintenance_manager"].includes(profile) || Boolean(notificationBase) && item.base === notificationBase);
  useScreenNotifications("records", notificationRecords.map(item=>({id:`${item.id}:${item.updatedAt}`,title:item.title,description:`${item.prefix} · ${item.recordType==="inspection"?typeLabel.inspection:reportTypes[item.technicalCase?.report??"report"]}`,at:item.updatedAt})), id=>{const item=notificationRecords.find(item=>`${item.id}:${item.updatedAt}`===id);if(item)setOpen(item);});
  async function create(item: MaintenanceRecord, files:File[]) { if(!supabase) return; item={...item,attachments:await uploadRecordMedia(supabase,files,`maintenance/${item.id}`,user)}; const { error } = await supabase.from("maintenance_records").insert({ id: item.id, record_type: item.recordType, base: item.base, model: item.model, prefix: item.prefix, priority: item.priority, status: item.status, title: item.title, tc: item.tc || null, source_flight_id: item.sourceFlightId ?? null, created_by: item.createdBy, data: payload(item), technical_case:item.technicalCase??initialTechnicalCase() }); if(error) { throw new Error(`Registro não criado: ${error.message}`); } setCreating(null); setDirectFault(false); onSeedConsumed?.(); await load(); }
  async function createMany(items: MaintenanceRecord[], files:Record<string,File[]>) { if(!supabase || !items.length) return; items=await Promise.all(items.map(async item=>({...item,attachments:await uploadRecordMedia(supabase,files[item.id]||[],`maintenance/${item.id}`,user)}))); const rows = items.map((item) => ({ id: item.id, record_type: item.recordType, base: item.base, model: item.model, prefix: item.prefix, priority: item.priority, status: item.status, title: item.title, tc: item.tc || null, created_by: item.createdBy, data: payload(item) })); const { error } = await supabase.from("maintenance_records").insert(rows); if(error) { throw new Error(`Serviços não programados: ${error.message}`); } setBatchCreating(false); await load(); }
  async function update(item: MaintenanceRecord) { if(!supabase) return; const { error } = await supabase.rpc("update_maintenance_record", { p_id: item.id, p_data: payload(item) }); if(error) { throw new Error(`Registro não atualizado: ${error.message}`); } setOpen(item); await load(); }
  async function remove(_item: MaintenanceRecord) { onError("Use Cancelamento com histórico no acompanhamento técnico."); }
  async function linkRecords(item: MaintenanceRecord, other: MaintenanceRecord) { if(!supabase) return; const at = now(); const nextItem = { ...item, links: [...new Set([...item.links, other.id])], entries: [...item.entries, { id: uid(), kind: "link" as const, description: `Vinculou ${typeLabel[other.recordType]} ${other.title}`, employeeNumber: user, at }], updatedAt: at }; const nextOther = { ...other, links: [...new Set([...other.links, item.id])], entries: [...other.entries, { id: uid(), kind: "link" as const, description: `Vinculado a ${item.recordType==="inspection"?typeLabel.inspection:reportTypes[item.technicalCase?.report??"report"]} ${item.title}`, employeeNumber: user, at }], updatedAt: at }; const first = await supabase.rpc("update_maintenance_record", { p_id: item.id, p_data: payload(nextItem) }); const second = await supabase.rpc("update_maintenance_record", { p_id: other.id, p_data: payload(nextOther) }); if(first.error || second.error) { onError(`Vínculo não concluído: ${(first.error ?? second.error)?.message}`); return; } setOpen(nextItem); await load(); }
  async function generateAction(item: MaintenanceRecord, category: string, title: string, assignedTo: string[], tc: string, plan: Record<string,string>) {
    if(!supabase || !leadership) return false;
    const { data, error } = await supabase.rpc("create_maintenance_request", {p_record_id:item.id,p_category:category,p_title:title,p_assigned_to:assignedTo,p_tc:tc,p_plan:plan});
    if(error || !data) { onError(`Ação não criada: ${error?.message || "Não houve confirmação do registro"}`); return false; }
    await load(); return true;
  }
  const currentAssignment = people.find((person) => person.employeeNumber === user);
  return <section>
    <DesktopActions>{mode !== "service" || leadership ? <button onClick={() => {setDirectFault(false); mode === "service" ? setBatchCreating(true) : setCreating(mode === "faults" ? "fault" : "discrepancy");}} style={mode === "service" ? {columnGap:4,whiteSpace:"nowrap"} : undefined} className="flex min-h-11 items-center gap-2 rounded-xl bg-[#1268d8] px-4 text-sm font-bold text-white"><Plus size={mode === "service" ? 16 : 18} />{mode === "service" ? "Programar serviço" : mode === "faults" ? "Novo relato técnico" : "Novo relato técnico"}</button> : null}{mode==="faults"&&["admin","app_manager","maintenance_inspector","maintenance_coordinator","maintenance_manager","maintenance_director"].includes(profile)?<button onClick={()=>{setDirectFault(true);setCreating("fault");}} className="flex min-h-11 items-center gap-2 rounded-xl border border-[#1268d8] bg-white px-4 text-sm font-bold text-[#1268d8]"><Plus size={18}/>Abrir pane</button>:null}</DesktopActions>
    <DesktopControls>
    <TechnicalAlerts client={supabase}/><RecordFilters mode={mode} filters={filters} setFilters={setFilters} aircraft={aircraft} bases={bases} models={models} modelOptions={modelOptions} prefixOptions={prefixOptions} />
</DesktopControls>
    {mode === "service" ? <ServiceTimeline items={visible} people={people} userDirectory={userDirectory} onOpen={setOpen} /> : <div className="mt-4 space-y-3">{visible.map((item) => <RecordCard chatCount={chatCounts[item.id]} user={user} directory={userDirectory} seenAt={recordReads[item.id]} onComments={()=>{setCommentsTarget(item.id);setOpen(item);}} key={item.id} item={item} onOpen={() => setOpen(item)} />)}{!visible.length ? <p className="rounded-2xl border border-dashed bg-white p-10 text-center text-sm text-[#718197]">Nenhum registro corresponde aos filtros.</p> : null}</div>}
    {creating ? <CreateRecord client={supabase} directFault={directFault} type={creating} aircraft={aircraft} people={people} seed={seed} user={user} assignment={currentAssignment} canAssign={leadership} onClose={() => { setCreating(null); setDirectFault(false); onSeedConsumed?.(); }} onCreate={async(item,files)=>{await requireSignature(()=>create(item,files),"Confirmar criação do registro");}} /> : null}
    {batchCreating ? <CreateServiceBatch aircraft={aircraft} people={people} user={user} assignment={currentAssignment} onClose={() => setBatchCreating(false)} onCreate={async(items,files)=>{await requireSignature(()=>createMany(items,files),"Confirmar serviços programados");}} /> : null}
    {open ? <RecordDialog startWithComments={commentsTarget===open.id} onCommentsRead={(at)=>setRecordReads(current=>({...current,[open.id]:at}))} canExecute={["mechanic","maintenance_director","maintenance_manager","maintenance_coordinator","maintenance_leader","maintenance_inspector"].includes(profile)} item={open} all={records} people={people} user={user} userDirectory={userDirectory} leadership={leadership} canDelete={false} supabase={supabase} requireSignature={requireSignature} onOpenTools={onOpenTools} onError={onError} onClose={() => {setOpen(null);setCommentsTarget(null);}} onDelete={() => void requireSignature(() => remove(open), "Confirmar exclusão")} onUpdate={(item) => update(item)} onLink={(other) => void requireSignature(() => linkRecords(open, other), "Confirmar vínculo")} onGenerate={async (category, title, assigned, tc, plan) => { let created=false; await requireSignature(async () => { created=await generateAction(open, category, title, assigned, tc, plan); }, "Confirmar criação da ação"); return created; }} /> : null}
  </section>;
}

function serviceDayLabel(value: string) {
  const date = new Date(value); const today = new Date(); const start = new Date(today.getFullYear(), today.getMonth(), today.getDate()); const target = new Date(date.getFullYear(), date.getMonth(), date.getDate()); const days = Math.round((start.getTime() - target.getTime()) / 86400000);
  if(days === 0) return "Hoje"; if(days === 1) return "Ontem"; if(days > 1 && days < 7) return date.toLocaleDateString("pt-BR", { weekday: "long" }); return date.toLocaleDateString("pt-BR");
}

function ServiceTimeline({ items, people, userDirectory, onOpen }: { items: MaintenanceRecord[]; people: Person[]; userDirectory: UserDirectory; onOpen: (item: MaintenanceRecord) => void }) {
  const ordered = [...items].sort((a, b) => Date.parse(b.updatedAt) - Date.parse(a.updatedAt));

  return <div className="mt-4 space-y-3">{ordered.map((item,index) => { const day = serviceDayLabel(item.updatedAt); const showDay = !index || day !== serviceDayLabel(ordered[index-1].updatedAt); const latest = [...item.entries].sort((a, b) => Date.parse(b.at) - Date.parse(a.at))[0]; const actor = people.find((person) => person.employeeNumber === (latest?.employeeNumber ?? item.createdBy)); const shift = actor?.workShift || item.originShift || ""; const mission = actor?.mission || item.originMission || ""; const night = shift === "night"; const latestResult = latest?.kind === "action" ? latest.result : undefined; return <div key={item.id}>{showDay ? <div className="sticky top-2 z-10 my-4 text-center"><span className="rounded-full bg-[#d9e7f5] px-3 py-1 text-xs font-extrabold capitalize text-[#315b86] shadow-sm">{day}</span></div> : null}<button onClick={() => onOpen(item)} className={`technical-card status-card w-full rounded-2xl border-l-4 p-4 min-[1100px]:py-3 text-left shadow-sm transition hover:-translate-y-0.5 ${item.recordType!=="inspection" ? technicalCardBorder(item.technicalCase||initialTechnicalCase()) : latestResult === "satisfactory" ? "border-emerald-500" : latestResult === "nonconforming" ? "border-red-500" : "border-amber-400"} ${night ? "bg-[#d6e1ee] text-[#132d49]" : "bg-white"}`}><div className="flex items-start justify-between gap-3"><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><strong className="font-mono text-base">{item.prefix}</strong><span className="status-label">{item.status==="closed"?"Encerrado":"Em aberto"}</span><span className="rounded-full bg-white/75 px-2 py-1 font-mono text-[10px] font-bold">{item.ticketCode}</span><span className="rounded-full bg-white/75 px-2 py-1 text-[10px] font-bold">{item.recordType==="inspection"?typeLabel.inspection:reportTypes[item.technicalCase?.report??"report"]}</span><span className="ml-auto hidden flex-wrap items-center gap-x-4 gap-y-1 text-[10px] opacity-70 min-[1100px]:flex"><span>{night ? "Noturno" : shift === "day" ? "Diurno" : "Turno não informado"}{mission ? ` · ${mission.replace("mission_", "Missão ")}` : ""}{item.tc ? ` · TC ${item.tc}` : ""}</span><span className="flex items-center gap-2"><UserAvatar employeeNumber={latest?.employeeNumber ?? item.createdBy} directory={userDirectory} size="xs" />{new Date(item.updatedAt).toLocaleTimeString("pt-BR", { hour: "2-digit", minute: "2-digit" })}</span></span></div><h4 className="mt-2 min-[1100px]:mt-1 line-clamp-2 font-extrabold">{item.title}</h4><p className="mt-1 line-clamp-2 text-sm opacity-75">{latest?.kind === "action" ? latest.description : item.description}</p></div><ChevronDown size={18} className="shrink-0" /></div><div className="mt-3 flex flex-wrap min-[1100px]:hidden items-center justify-between gap-2 text-[10px] opacity-70"><span>{night ? "Noturno" : shift === "day" ? "Diurno" : "Turno não informado"}{mission ? ` · ${mission.replace("mission_", "Missão ")}` : ""}{item.tc ? ` · TC ${item.tc}` : ""}</span><span className="flex items-center gap-2"><UserAvatar employeeNumber={latest?.employeeNumber ?? item.createdBy} directory={userDirectory} size="xs" />{new Date(item.updatedAt).toLocaleTimeString("pt-BR", { hour: "2-digit", minute: "2-digit" })}</span></div></button></div>; })}{!ordered.length ? <p className="rounded-2xl border border-dashed bg-white p-10 text-center text-sm text-[#718197]">Nenhum serviço corresponde aos filtros.</p> : null}</div>;
}

type ServiceDraft = { id: string; prefix: string; title: string; description: string; tc: string };
function CreateServiceBatch({ aircraft, people, user, assignment, onClose, onCreate }: { aircraft: Aircraft[]; people: Person[]; user: string; assignment?: Person; onClose: () => void; onCreate: (items: MaintenanceRecord[],files:Record<string,File[]>) => Promise<void> }) {
  const [files,setFiles]=useState<Record<string,File[]>>({});const [saving,setSaving]=useState(false);const [error,setError]=useState("");
  const blank = (): ServiceDraft => ({ id: uid(), prefix: "", title: "", description: "", tc: "" }); const [drafts, setDrafts] = useState<ServiceDraft[]>([blank()]); const [assigned, setAssigned] = useState<string[]>([]); const shift = assignment?.workShift as "day" | "night" | undefined; const mission = assignment?.mission ?? "";
  function updateDraft(id: string, patch: Partial<ServiceDraft>) { setDrafts((items) => items.map((item) => item.id === id ? { ...item, ...patch } : item)); }
  async function submit() { if(!shift || !mission || drafts.some((draft) => !draft.prefix || !draft.title.trim() || !draft.description.trim())) return; const at = now();setSaving(true);setError("");try{await onCreate(drafts.map((draft) => { const selected = aircraft.find((item) => item.prefix === draft.prefix)!; return { id: draft.id, ticketCode: "", recordType: "inspection", base: selected.base, model: selected.model, prefix: selected.prefix, priority: "routine", originShift: shift, originMission: mission, status: "open", title: draft.title.trim(), description: draft.description.trim(), tc: draft.tc.trim(), assignedTo: assigned, links: [], entries: assigned.length ? [{ id: uid(), kind: "assignment", description: `Designado para ${assigned.join(", ")}`, employeeNumber: user, at }] : [], createdBy: user, createdAt: at, updatedAt: at, revision: 1 }; }),files);}catch(err){setError((err as Error).message);}finally{setSaving(false);} }
  const valid = Boolean(shift && mission && drafts.every((draft) => draft.prefix && draft.title.trim() && draft.description.trim()));
  return <Dialog title="Programar serviços" onClose={onClose} wide><div className="space-y-4"><div className={`rounded-xl px-4 py-3 text-sm font-bold ${shift === "night" ? "bg-[#d6e1ee] text-[#17324d]" : "bg-[#edf5fc] text-[#315b86]"}`}>{shift === "night" ? "Noturno" : shift === "day" ? "Diurno" : "Turno não definido"} · {mission ? mission.replace("mission_", "Missão ") : "Missão não definida"}<p className="mt-1 text-xs font-normal opacity-70">Informações preenchidas automaticamente pela escala.</p></div>{drafts.map((draft, index) => <section key={draft.id} className={`rounded-2xl border p-4 ${shift === "night" ? "bg-[#dce6f0]" : "bg-white"}`}><div className="mb-3 flex items-center justify-between"><strong>Serviço {index + 1}</strong>{drafts.length > 1 ? <button onClick={() => setDrafts((items) => items.filter((item) => item.id !== draft.id))} className="text-xs font-bold text-red-600">Remover</button> : null}</div><div className="grid gap-3 sm:grid-cols-2"><Field label="Prefixo"><SearchableSelect value={draft.prefix} onValueChange={(event) => updateDraft(draft.id, { prefix: event })}><option value="">Selecione</option>{aircraft.map((item) => <option key={item.prefix}>{item.prefix}</option>)}</SearchableSelect></Field><Field label="TC (opcional)"><input value={draft.tc} onChange={(event) => updateDraft(draft.id, { tc: event.target.value })} /></Field></div><div className="mt-3"><Field label="Título"><input value={draft.title} onChange={(event) => updateDraft(draft.id, { title: event.target.value })} /></Field></div><div className="mt-3"><Field label="Descrição"><textarea rows={3} value={draft.description} onChange={(event) => updateDraft(draft.id, { description: event.target.value })} /></Field></div><MediaPicker documents files={files[draft.id]||[]} onChange={next=>setFiles(current=>({...current,[draft.id]:next}))} disabled={saving}/></section>)}<button onClick={() => setDrafts((items) => [...items, blank()])} className="flex items-center gap-2 rounded-xl border border-[#1268d8] px-4 py-2.5 text-sm font-bold text-[#1268d8]"><Plus size={16} />Adicionar outro serviço</button><AssignmentPicker people={people} value={assigned} onChange={setAssigned} />{error?<p role="alert" className="text-sm text-red-700">{error}</p>:null}<div className="flex justify-end gap-2"><button onClick={onClose} className="rounded-xl border px-4 py-2">Cancelar</button><button disabled={!valid||saving} onClick={submit} className="rounded-xl bg-[#1268d8] px-4 py-2 font-bold text-white disabled:opacity-40">Publicar {drafts.length} serviço{drafts.length === 1 ? "" : "s"}</button></div></div></Dialog>;
}

function RecordFilters({ mode, filters, setFilters, aircraft, bases, models, modelOptions, prefixOptions }: { mode: "faults" | "discrepancies" | "service"; filters: { base: string; model: string; prefix: string; status: string; priority: string; urgency: string; report: string; aircraftState:string; investigation:string; from:string; until:string; }; setFilters: React.Dispatch<React.SetStateAction<typeof filters>>; aircraft: Aircraft[]; bases: string[]; models: string[]; modelOptions: string[]; prefixOptions: string[]; }) {
  const [filtersOpen, setFiltersOpen] = useState(false);
  const control = "h-11 w-full rounded-xl border border-[#c8d7e6] bg-white px-3 text-sm shadow-sm outline-none focus:border-[#1769e0]";
  function changeBase(base: string) { setFilters((current) => { const validModels = [...new Set(aircraft.filter((item) => !base || item.base === base).map((item) => item.model))]; const model = current.model && validModels.includes(current.model) ? current.model : ""; const prefix = current.prefix && aircraft.some((item) => (!base || item.base === base) && (!model || item.model === model) && item.prefix.includes(current.prefix)) ? current.prefix : ""; return { ...current, base, model, prefix }; }); }
  function changeModel(model: string) { setFilters((current) => { const prefix = current.prefix && aircraft.some((item) => (!current.base || item.base === current.base) && (!model || item.model === model) && item.prefix.includes(current.prefix)) ? current.prefix : ""; return { ...current, model, prefix }; }); }
  const priorityOptions = Object.entries(officialStates);
  return <section className="rounded-2xl border border-[#dce6f0] bg-white p-4 shadow-sm"><button type="button" aria-expanded={filtersOpen} onClick={() => setFiltersOpen((value) => !value)} className="flex min-h-7 w-full items-center justify-between text-left font-bold text-[#36546f]"><span className="flex items-center gap-2"><Search size={17} />Filtros</span><ChevronDown size={18} className={`transition ${filtersOpen ? "rotate-180" : ""}`} /></button><div className={`record-filter-fields ${filtersOpen ? "grid" : "hidden"} mt-4 gap-3 sm:grid-cols-2 lg:grid-cols-5`}><div><RecentDateFilter from={filters.from} until={filters.until} onChange={(from,until)=>setFilters(f=>({...f,from,until}))}/>{filters.from===localFilterDay()&&filters.until===localFilterDay()?<p className="mt-2 text-xs text-[#52677f]">{mode==="service"?"Pendências permanecem até a resolução, inclusive de dias anteriores.":"Inclui casos em investigação e acompanhamento de dias anteriores."}</p>:null}</div><FilterField label="Base"><select aria-label="Filtrar por base" value={filters.base} onChange={(e) => changeBase(e.target.value)} className={control}><option value="">Todas as bases</option>{bases.map((v) => <option key={v}>{v}</option>)}</select></FilterField><FilterField label="Modelo"><select aria-label="Filtrar por modelo" value={filters.model} onChange={(e) => changeModel(e.target.value)} className={control}><option value="">Todos os modelos</option>{(modelOptions.length ? modelOptions : models).map((v) => <option key={v}>{v}</option>)}</select></FilterField><FilterField label="Prefixo"><div className="relative"><Search size={14} className="pointer-events-none absolute left-3 top-3.5 text-[#718197]" /><input aria-label="Filtrar por prefixo" list="record-prefixes" value={filters.prefix} onChange={(e) => setFilters((f) => ({ ...f, prefix: e.target.value.toUpperCase() }))} placeholder="Digite ou selecione" className={`${control} pl-8 uppercase`} /><datalist id="record-prefixes">{prefixOptions.map((v) => <option key={v} value={v} />)}</datalist></div></FilterField><FilterField label="Situação"><select aria-label="Filtrar por situação" value={filters.status} onChange={(e) => setFilters((f) => ({ ...f, status: e.target.value }))} className={control}><option value="">Todas as situações</option><option value="open">Em aberto</option><option value="closed">Encerrado</option></select></FilterField><FilterField label="Prioridade"><select aria-label="Filtrar por prioridade" value={filters.urgency} onChange={e=>setFilters(f=>({...f,urgency:e.target.value}))} className={control}><option value="">Todas</option>{Object.entries(technicalPriorities).map(([v,l])=><option key={v} value={v}>{l}</option>)}</select></FilterField><FilterField label="Vínculo Oficial"><select aria-label="Filtrar por vínculo oficial" value={filters.priority} onChange={(e) => setFilters((f) => ({ ...f, priority: e.target.value }))} className={control}><option value="">Todas as classificações</option>{priorityOptions.map(([value, label]) => <option key={value} value={value}>{label}</option>)}</select></FilterField>{([["report","Tipo do Relato",reportTypes],["aircraftState","Situação da Aeronave",aircraftStates],["investigation","Estágio da Investigação",investigationStates]] as const).map(([key,label,options])=><FilterField key={key} label={label}><select className={control} value={filters[key]} onChange={e=>setFilters(f=>({...f,[key]:e.target.value}))}><option value="">Todas as opções</option>{key==="investigation"?<option value="following">Em acompanhamento (todos)</option>:null}{Object.entries(options).map(([v,l])=><option key={v} value={v}>{l}</option>)}</select></FilterField>)}</div></section>;
}
function FilterField({ label, children }: { label: string; children: React.ReactNode; }) { return <label><span className="mb-1.5 block text-xs font-extrabold text-[#526b82]">{label}</span>{children}</label>; }

function RecordCard({ chatCount,item, onOpen,onComments,user,directory,seenAt }: { item: MaintenanceRecord; onOpen: () => void;onComments:()=>void;user:string;directory:UserDirectory;seenAt?:string;chatCount?:{message_count:number;unread:number}; }) { const immediate = isUrgentTechnical(item.technicalCase); const latestResult = [...item.entries].filter((entry) => entry.kind === "action" && entry.result).sort((a, b) => Date.parse(b.at) - Date.parse(a.at))[0]?.result; const classification = null; return <article className={`technical-card status-card w-full rounded-2xl border-l-4 bg-white p-4 text-left shadow-sm ${technicalCardBorder(item.technicalCase||initialTechnicalCase())}`}><button onClick={onOpen} className="block w-full text-left"><div className="flex items-start justify-between gap-3"><div><div className="flex flex-wrap items-center gap-2"><strong className="font-mono text-lg">{item.prefix}</strong><span className="status-label">{item.status==="closed"?"Encerrado":"Em aberto"}</span>{item.ticketCode ? <span className="rounded-full bg-slate-100 px-2 py-1 font-mono text-[10px] font-bold text-slate-700">{item.ticketCode}</span> : null}<span className="rounded-full bg-[#edf4fb] px-2 py-1 text-[10px] font-bold">{item.recordType==="inspection"?typeLabel.inspection:reportTypes[item.technicalCase?.report??"report"]}</span><span className="rounded-full bg-indigo-50 px-2 py-1 text-[10px] font-bold text-indigo-700">Turno {item.originShift === "day" ? "diurno" : item.originShift === "night" ? "noturno" : "não informado"}</span>{classification ? <span className={`rounded-full px-2 py-1 text-[10px] font-bold ${immediate ? "bg-red-50 text-red-700" : "bg-amber-50 text-amber-700"}`}>{classification}</span> : null}{latestResult ? <span className={`rounded-full px-2 py-1 text-[10px] font-bold ${latestResult === "satisfactory" ? "bg-emerald-100 text-emerald-800" : "bg-red-100 text-red-800"}`}>{latestResult === "satisfactory" ? "Última ação OK" : "Última ação não OK"}</span> : null}</div><h4 className="mt-2 font-bold">{item.title}</h4><p className="mt-1 line-clamp-2 text-sm text-[#60758c]">{item.description}</p></div><ChevronDown size={18} /></div><div className="mt-3 flex flex-wrap gap-3 text-[10px] text-[#718197]"><span>{item.base} · {item.model}</span><span><Clock3 size={11} className="mr-1 inline" />{dateTime(item.updatedAt)}</span>{item.tc ? <span>TC: {item.tc}</span> : null}<span>{item.entries.filter((entry) => entry.kind === "action").length} execução(ões)</span></div></button><button onClick={()=>requestRecordChat(item.id)} className="mt-3 rounded-lg bg-emerald-50 px-3 py-2 text-xs font-bold text-emerald-800"><MessageCircle size={14} className="mr-1 inline"/>{chatCount?`Minhas conversas · ${chatCount.message_count} mensagens · ${chatCount.unread} novas`:"Iniciar conversa"}</button><div className="mt-3"><CommentSummary comments={item.entries.filter(e=>e.kind==="comment").map(e=>({id:e.id,employeeNumber:e.employeeNumber,at:e.at,body:e.description}))} directory={directory} designator={taskDesignator(item.entries)} pinnedId={item.pinnedCommentId} newCount={item.entries.filter(e=>e.kind==="comment"&&e.employeeNumber!==user&&(!seenAt||Date.parse(e.at)>Date.parse(seenAt))).length} onOpen={onComments}/></div></article>; }

export function CreateRecord({ client,directFault=false,type, aircraft, people, seed, user, assignment, canAssign, onClose, onCreate }: { client:SupabaseClient|null; directFault?:boolean; type: MaintenanceRecord["recordType"]; aircraft: Aircraft[]; people: Person[]; seed?: { type: "fault" | "discrepancy"; prefix: string; sourceFlightId: string; } | null; user: string; assignment?: Person; canAssign: boolean; onClose: () => void; onCreate: (item: MaintenanceRecord,files:File[]) => Promise<void>; }) { const assistantWorkspace=useAssistantWorkspace();const [aiOpen,setAiOpen]=useState(false);const [files,setFiles]=useState<File[]>([]);const [saving,setSaving]=useState(false);const [error,setError]=useState("");const [urgency,setUrgency]=useState<"routine"|"urgent">("routine");const [officialId,setOfficialId]=useState("");const [originalObservation,setOriginalObservation]=useState<{title:string;description:string;spoken:string}|null>(null);const [recordId]=useState(uid); const [prefix, setPrefix] = useState(seed?.prefix ?? ""); const [title, setTitle] = useState(""); const [description, setDescription] = useState(""); const [tc, setTc] = useState(""); const priority:MaintenancePriority = type === "fault" ? "not_logged" : "routine"; const [assigned, setAssigned] = useState<string[]>([]); const selected = aircraft.find((a) => a.prefix === prefix); const originShift = assignment?.workShift === "night" ? "night" : "day"; const originMission = assignment?.mission ?? ""; async function submit() { if(!selected || !title.trim() || !description.trim() || !priority) return; if(directFault&&!tc.trim()){setError("Informe o número da TC para abrir a pane.");return;} const at = now(); const assignedTo = canAssign ? assigned : []; setSaving(true);setError("");try{await onCreate({ technicalCase:{...initialTechnicalCase(),originalObservation:originalObservation||{title,description,spoken:"",at},...(directFault?{report:"discrepancy" as const,official:"pending" as const}:{}),priority:urgency,...(officialId.trim()?{official:"linked" as const,officialId:officialId.trim()}:{} )}, id: recordId, ticketCode: "", recordType: type, base: selected.base, model: selected.model, prefix: selected.prefix, priority, originShift, originMission, status: "open", title: title.trim(), description: description.trim(), tc: tc.trim(), sourceFlightId: seed?.sourceFlightId, assignedTo, links: [], entries: assignedTo.length ? [{ id: uid(), kind: "assignment", description: `Designado para ${assignedTo.join(", ")}`, employeeNumber: user, at }] : [], createdBy: user, createdAt: at, updatedAt: at, revision: 1 },files);}catch(err){setError((err as Error).message);}finally{setSaving(false);} } return <Dialog assistantWide={aiOpen} title={directFault?"Abrir pane":`Novo ${typeLabel[type].toLowerCase()}`} onClose={onClose}><div className={aiOpen?"grid min-w-0 gap-4 lg:grid-cols-2":""}><div className="min-w-0 space-y-3"><button type="button" aria-expanded={aiOpen} disabled={saving} onClick={()=>assistantWorkspace?assistantWorkspace.open(recordId):setAiOpen(true)} className="min-h-11 rounded-xl border border-blue-200 bg-blue-50 px-4 text-sm font-bold text-blue-800">Conversar com IA neste relato</button><div className={`rounded-xl px-3 py-2 text-xs font-bold ${originShift === "night" ? "bg-[#d6e1ee]" : "bg-[#edf5fc]"}`}>{originShift === "night" ? "Noturno" : "Diurno"}{originMission ? ` · ${originMission.replace("mission_", "Missão ")}` : ""}<span className="ml-2 font-normal opacity-70">Preenchido pela escala</span></div><Field label="Prefixo"><SearchableSelect value={prefix} onValueChange={(e) => setPrefix(e)}><option value="">Selecione</option>{aircraft.map((a) => <option key={a.prefix}>{a.prefix}</option>)}</SearchableSelect></Field><Field label="Título"><input aria-label="Título" value={title} onChange={(e) => setTitle(e.target.value)} /></Field><Field label="Descrição"><textarea aria-label="Descrição" rows={5} value={description} onChange={(e) => setDescription(e.target.value)} /></Field><Field label={directFault?"Número da TC (obrigatório)":"TC (opcional)"}><input aria-label={directFault?"Número da TC (obrigatório)":"TC (opcional)"} required={directFault} value={tc} onChange={(e) => setTc(e.target.value)} /></Field><Field label="Prioridade"><select value={urgency} onChange={e=>setUrgency(e.target.value as "routine"|"urgent")}><option value="routine">Rotina · acompanhar no relato</option><option value="urgent">Urgente · destacar no Ao vivo</option></select></Field><details open={directFault||undefined} className="rounded-lg border p-3"><summary className="cursor-pointer text-sm font-bold">Já existe pane no eDB? Vincular</summary><Field label="Identificador no eDB (opcional)"><input value={officialId} onChange={e=>setOfficialId(e.target.value)}/></Field><p className="text-xs">Informe o registro já criado. A avaliação técnica permanece com o profissional autorizado.</p></details><p className="text-xs text-slate-600">{directFault?"Informe a TC da pane já registrada. O número é uma referência informada pelo responsável; ainda não há consulta automática ao WinAir/eDB. O identificador específico do eDB permanece separado.":"Novo Relato Técnico · aguardando triagem. A classificação e o vínculo oficial serão avaliados pela equipe autorizada."}</p><TechnicalDraftReview text={description}/>{canAssign ? <AssignmentPicker people={people} value={assigned} onChange={setAssigned} /> : null}<MediaPicker documents files={files} onChange={setFiles} disabled={saving}/>{error?<p role="alert" className="text-sm text-red-700">{error}</p>:null}<div className="flex justify-end gap-2"><button onClick={onClose} className="rounded-xl border px-4 py-2">Cancelar</button><button disabled={saving || !selected || !title.trim() || !description.trim() || !priority || (directFault&&!tc.trim())} onClick={submit} className="rounded-xl bg-[#1268d8] px-4 py-2 font-bold text-white disabled:opacity-40">{saving?"Enviando e salvando…":"Criar registro"}</button></div></div>{assistantWorkspace?<AssistantTarget id={recordId} label={`Novo relato · ${prefix||"selecione a aeronave"}`} revision={JSON.stringify([title,description,prefix,tc,saving,aircraft])} content={<ContextualAssistant open={true} context={{kind:"maintenance-draft",id:recordId,prefix,model:selected?.model||"",aircraft:aircraft.map(a=>({prefix:a.prefix,model:a.model})),fields:{title,description,prefix,tc}}} client={client} user={user} disabled={saving} onClose={()=>assistantWorkspace.close()} onApply={(fields,original)=>{if(original)setOriginalObservation(current=>current||original);setTitle(fields.title);setDescription(fields.description);if(fields.prefix!==undefined)setPrefix(fields.prefix);if(fields.tc!==undefined)setTc(fields.tc);}}/>}/>:aiOpen?<ContextualAssistant open={true} context={{kind:"maintenance-draft",id:recordId,prefix,model:selected?.model||"",aircraft:aircraft.map(a=>({prefix:a.prefix,model:a.model})),fields:{title,description,prefix,tc}}} client={client} user={user} disabled={saving} onClose={()=>{setAiOpen(false);}} onApply={(fields,original)=>{if(original)setOriginalObservation(current=>current||original);setTitle(fields.title);setDescription(fields.description);if(fields.prefix!==undefined)setPrefix(fields.prefix);if(fields.tc!==undefined)setTc(fields.tc);}}/>:null}</div></Dialog>; }



function LinkPicker({ current, records, onLink }: { current: MaintenanceRecord; records: MaintenanceRecord[]; onLink: (record: MaintenanceRecord) => void; }) {
  const [base, setBase] = useState(""); const [model, setModel] = useState(""); const [prefix, setPrefix] = useState(current.prefix); const [type, setType] = useState(""); const [status, setStatus] = useState(""); const [search, setSearch] = useState(""); const [filtersOpen, setFiltersOpen] = useState(false);
  const available = records.filter((record) => record.id !== current.id && !current.links.includes(record.id));
  const bases = [...new Set(available.map((record) => record.base))].sort();
  const models = [...new Set(available.filter((record) => !base || record.base === base).map((record) => record.model))].sort();
  const prefixes = [...new Set(available.filter((record) => (!base || record.base === base) && (!model || record.model === model)).map((record) => record.prefix))].sort();
  const results = available.filter((record) => (!base || record.base === base) && (!model || record.model === model) && (!prefix || record.prefix.includes(prefix.toUpperCase())) && (!type || record.recordType === type) && (!status || record.status === status) && (!search || `${record.ticketCode} ${record.title} ${record.description} ${record.tc}`.toLowerCase().includes(search.toLowerCase()))).sort((a, b) => Date.parse(b.updatedAt) - Date.parse(a.updatedAt));
  return <section className="rounded-xl border bg-[#f4f7fb] p-3"><h4 className="font-bold">Vincular ocorrência</h4><p className="mt-1 text-xs text-[#718197]">Filtre os registros e selecione a ocorrência relacionada.</p><div className="mt-3 rounded-xl border bg-white p-3"><button type="button" aria-expanded={filtersOpen} onClick={() => setFiltersOpen((value) => !value)} className="flex min-h-7 w-full items-center justify-between text-left font-bold text-[#36546f]"><span className="flex items-center gap-2"><Search size={16} />Filtros</span><ChevronDown size={17} className={filtersOpen ? "rotate-180" : ""} /></button><div className={`${filtersOpen ? "grid" : "hidden"} mt-3 gap-2 sm:grid-cols-3`}><select value={base} onChange={(event) => { setBase(event.target.value); setModel(""); setPrefix(""); }}><option value="">Todas as bases</option>{bases.map((value) => <option key={value}>{value}</option>)}</select><select value={model} onChange={(event) => { setModel(event.target.value); setPrefix(""); }}><option value="">Todos os modelos</option>{models.map((value) => <option key={value}>{value}</option>)}</select><div><input list="link-prefixes" value={prefix} onChange={(event) => setPrefix(event.target.value.toUpperCase())} placeholder="Digite ou selecione o prefixo" /><datalist id="link-prefixes">{prefixes.map((value) => <option key={value} value={value} />)}</datalist></div><select value={type} onChange={(event) => setType(event.target.value)}><option value="">Relato Técnico ou caso técnico</option><option value="fault">Relato Técnico</option><option value="discrepancy">Caso Técnico</option><option value="inspection">Programada</option></select><select value={status} onChange={(event) => setStatus(event.target.value)}><option value="">Todas as situações</option><option value="open">Em aberto</option><option value="closed">Encerrada</option></select><input value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Título, descrição, TC ou ticket" /></div></div><div className="mt-3 max-h-72 space-y-2 overflow-y-auto">{results.map((record) => <button key={record.id} onClick={() => onLink(record)} className="flex w-full items-start justify-between gap-3 rounded-xl border bg-white p-3 text-left hover:border-[#6ea4df]"><span><b className="block text-sm">{record.ticketCode || `${typeLabel[record.recordType]} · ${record.prefix}`}</b><span className="mt-1 block text-xs font-semibold">{record.prefix} · {typeLabel[record.recordType]} · {record.title}</span><small className="mt-1 block text-[#718197]">{record.base} · {record.model} · {record.status === "open" ? "Em aberto" : "Encerrada"}{record.tc ? ` · TC ${record.tc}` : ""}</small></span><Link2 size={16} className="mt-1 shrink-0 text-[#1769e0]" /></button>)}{!results.length ? <p className="rounded-xl border border-dashed bg-white p-6 text-center text-xs text-[#718197]">Nenhuma ocorrência corresponde aos filtros.</p> : null}</div></section>;
}

function RecordDialog({ startWithComments,onCommentsRead,canExecute, item, all, people, user, userDirectory, leadership, canDelete, supabase, requireSignature, onOpenTools, onError, onClose, onDelete, onUpdate, onLink, onGenerate }: { startWithComments?:boolean;onCommentsRead:(at:string)=>void;canExecute:boolean; item: MaintenanceRecord; all: MaintenanceRecord[]; people: Person[]; user: string; userDirectory: UserDirectory; leadership: boolean; canDelete: boolean; supabase: SupabaseClient | null; requireSignature: (action: () => void | Promise<void>, label?: string) => Promise<boolean>; onOpenTools?: () => void; onError: (message: string) => void; onClose: () => void; onDelete: () => void; onUpdate: (item: MaintenanceRecord) => Promise<void>; onLink: (other: MaintenanceRecord) => void; onGenerate: (category: string, title: string, assigned: string[], tc: string, plan: Record<string,string>) => Promise<boolean>; }) {
  useEffect(()=>{const close=()=>onClose();window.addEventListener('flight-ia-chat-record',close);return()=>window.removeEventListener('flight-ia-chat-record',close);},[onClose]);
  const [recordFiles,setRecordFiles]=useState<File[]>([]);const [executionFiles,setExecutionFiles]=useState<File[]>([]);const [actionFiles,setActionFiles]=useState<File[]>([]);
  const [commentSeen,setCommentSeen]=useState<string|null>(null);
  useEffect(()=>{if(!supabase)return;let active=true;void supabase.from("technical_comment_reads").select("seen_at").eq("record_id",item.id).maybeSingle().then(({data})=>{if(active)setCommentSeen(data?.seen_at||null);});return()=>{active=false;};},[supabase,item.id,user]);
  async function seeComments(){document.getElementById(`record-comments-${item.id}`)?.setAttribute("open","");const latest=combinedComments.map(c=>c.at).sort().at(-1);if(!supabase||!latest)return;const{error}=await supabase.rpc("read_technical_comments",{p_record_id:item.id,p_seen_at:latest});if(error){onError(error.message);return;}setCommentSeen(latest);onCommentsRead(latest);}
  const [description, setDescription] = useState(""); const [comment, setComment] = useState(""); const [commentFiles, setCommentFiles] = useState<File[]>([]); const [result, setResult] = useState<"satisfactory" | "nonconforming">("satisfactory"); const [saving, setSaving] = useState(false); const [linking, setLinking] = useState(false); const [generating, setGenerating] = useState(false); const [actionCreated,setActionCreated]=useState(false); const [createdCategory,setCreatedCategory]=useState(""); const [category, setCategory] = useState("Giro em baixa"); const [actionTitle, setActionTitle] = useState(""); const [generatedTc, setGeneratedTc] = useState(""); const [operationPlan,setOperationPlan]=useState<Record<string,string>>({}); const [assigned, setAssigned] = useState<string[]>([]); const categories = availableMaintenanceCategories(item.model); const relatedRecords = [item, ...all.filter((record) => record.id !== item.id && item.links.includes(record.id))]; const combinedEntries = relatedRecords.flatMap((record) => record.entries.filter((entry) => entry.kind !== "comment").map((entry) => ({ ...entry, origin: record.id === item.id ? "Registro atual" : `${typeLabel[record.recordType]} · ${record.title}` }))).sort((a, b) => Date.parse(b.at) - Date.parse(a.at)); const combinedComments = relatedRecords.flatMap((record) => record.entries.filter((entry) => entry.kind === "comment").map((entry) => ({ ...entry, origin: record.id === item.id ? "Registro atual" : `${typeLabel[record.recordType]} · ${record.title}` }))).sort((a, b) => Date.parse(a.at) - Date.parse(b.at));
  async function addRecordMedia(){if(!recordFiles.length||saving||!supabase)return;setSaving(true);try{await requireSignature(async()=>{const attachments=await uploadRecordMedia(supabase,recordFiles,`maintenance/${item.id}`,user);const{error}=await supabase.rpc("append_maintenance_media",{p_id:item.id,p_attachments:attachments});if(error)throw error;setRecordFiles([]);},"Confirmar anexos do registro");}catch(err){onError((err as Error).message);}finally{setSaving(false);}}
  async function addExecution(){if(!description.trim()||saving)return;setSaving(true);try{await requireSignature(async()=>{const attachments=await uploadRecordMedia(supabase,executionFiles,`maintenance/${item.id}`,user);const person=people.find(p=>p.employeeNumber===user);await onUpdate({...item,entries:[...item.entries,{id:uid(),kind:"action",description:description.trim(),result,employeeNumber:user,at:now(),workShift:person?.workShift,mission:person?.mission,attachments}],updatedAt:now()});setDescription("");setExecutionFiles([]);},"Confirmar execução da manutenção");}catch(err){onError((err as Error).message);}finally{setSaving(false);}}
  async function addComment(){if((!comment.trim()&&!commentFiles.length)||saving)return;setSaving(true);try{const attachments=await uploadRecordMedia(supabase,commentFiles,`maintenance/${item.id}`,user);await onUpdate({...item,entries:[...item.entries,{id:uid(),kind:"comment",description:comment.trim(),employeeNumber:user,at:now(),attachments}],updatedAt:now()});setComment("");setCommentFiles([]);}catch(err){onError((err as Error).message);}finally{setSaving(false);}}
  async function submitGeneratedAction() { if(!actionTitle.trim() || saving) return; setSaving(true); try { const attachments=await uploadRecordMedia(supabase,actionFiles,`maintenance/${item.id}`,user);const created=await onGenerate(category, actionTitle.trim(), assigned, generatedTc, {...operationPlan,attachments:JSON.stringify(attachments)}); if(created) { setGenerating(false); setActionTitle(""); setGeneratedTc(""); setAssigned([]); setActionCreated(true); setCreatedCategory(category);setActionFiles([]); } } catch(err){onError((err as Error).message);} finally { setSaving(false); } }
  function toggleStatus() { void requireSignature(() => onUpdate({ ...item, status: item.status === "open" ? "closed" : "open", entries: [...item.entries, { id: uid(), kind: "status", description: item.status === "open" ? "Registro encerrado" : "Registro reaberto", employeeNumber: user, at: now() }], updatedAt: now() }), item.status === "open" ? "Confirmar encerramento" : "Confirmar reabertura").catch(err=>onError((err as Error).message)); }
  const classification = null; const shiftLabel = item.originShift === "day" ? "Diurno" : item.originShift === "night" ? "Noturno" : "Não informado";
  return <Dialog title={`${item.recordType==="inspection"?typeLabel.inspection:reportTypes[item.technicalCase?.report??"report"]} · ${item.prefix}${item.ticketCode ? ` · ${item.ticketCode}` : ""}`} onClose={onClose} wide><div className="space-y-4"><div className="flex flex-wrap gap-2"><button onClick={() => setLinking(!linking)} className="flex items-center gap-1 rounded-lg border px-3 py-2 text-xs font-bold"><Link2 size={14} />Vincular ocorrência</button>{leadership ? <button onClick={() => { setGenerating(!generating); setActionCreated(false); }} className="flex items-center gap-2 rounded-lg bg-[#1268d8] px-4 py-2.5 text-xs font-black text-white shadow-sm"><Wrench size={15} />GERAR AÇÃO</button> : null}{leadership && item.recordType==="inspection" ? <button onClick={toggleStatus} className="flex items-center gap-1 rounded-lg bg-[#0d315e] px-3 py-2 text-xs font-bold text-white">{item.status === "open" ? <CheckCircle2 size={14} /> : <RotateCcw size={14} />} {item.status === "open" ? "Encerrar" : "Reabrir"}</button> : null}</div><RecordConversation recordId={item.id} client={supabase}/>{item.recordType!=="inspection"?<TechnicalCasePanel user={user} prefix={item.prefix} model={item.model} key={`${item.id}:${item.revision}`} client={supabase} id={item.id} revision={item.revision} value={item.technicalCase} tc={item.tc} title={item.title} description={item.description} requireSignature={requireSignature} onSaved={onClose}/>:null}<section><div className="flex flex-wrap gap-2"><b>{item.title}</b><span className="rounded-full bg-[#edf4fb] px-2 py-1 text-xs">{item.status === "open" ? "Em aberto" : "Encerrado"}</span><span className="rounded-full bg-indigo-50 px-2 py-1 text-xs font-bold text-indigo-700">Turno {shiftLabel.toLowerCase()}</span>{classification ? <span className={`rounded-full px-2 py-1 text-xs font-bold ${item.priority === "urgent" || item.priority === "logged" ? "bg-red-50 text-red-700" : "bg-amber-50 text-amber-700"}`}>{classification}</span> : null}{item.links.length ? <span className="rounded-full bg-blue-50 px-2 py-1 text-xs font-bold text-blue-700">{item.links.length + 1} ocorrências relacionadas</span> : null}</div><p className="mt-3 whitespace-pre-wrap text-sm">{item.description}</p><MediaGallery items={item.attachments} supabase={supabase}/>{canExecute||leadership||canDelete?<div className="mt-3 rounded-xl border p-3"><b className="text-sm">Anexos do registro</b><MediaPicker documents files={recordFiles} onChange={setRecordFiles} disabled={saving}/><button disabled={saving||!recordFiles.length} onClick={()=>void addRecordMedia()} className="rounded-lg bg-blue-600 px-3 py-2 text-xs font-bold text-white disabled:opacity-40">{saving?"Enviando…":"Salvar anexos"}</button></div>:null}<p className="mt-2 text-xs text-[#718197]">Aberto por mat. {item.createdBy} · Turno {shiftLabel.toLowerCase()} · {dateTime(item.createdAt)}{item.tc ? ` · TC ${item.tc}` : ""}</p></section>{linking ? <LinkPicker current={item} records={all} onLink={onLink} /> : null}{actionCreated ? <p role="status" className="rounded-xl bg-green-50 p-3 text-sm font-bold text-green-800">{`Ação criada. ${maintenanceAudienceHint(createdCategory)}`}</p> : null}{generating ? <section className="space-y-2 rounded-xl bg-[#f4f7fb] p-3"><h4 className="font-bold">Gerar ação vinculada</h4><p className="text-xs text-[#52677f]">Programe o próximo giro ou serviço e selecione quem vai executá-lo. A atividade ficará pendente até o registro da execução.</p><AssistantForm client={supabase} user={user} disabled={saving} form={{id:`action-draft:${item.id}`,label:`Gerar ação · ${item.prefix}`,mode:'draft',fields:{title:{label:'Finalidade da próxima ação solicitada, não execução concluída',value:actionTitle,maxLength:4000},tc:{label:'TC / OS',value:generatedTc,maxLength:160},category:{label:'Tipo de ação',value:category,options:categories}}}} onApply={values=>{if(values.title!==undefined)setActionTitle(values.title);if(values.tc!==undefined)setGeneratedTc(values.tc);if(values.category!==undefined)setCategory(values.category);}}/><ActionFields categories={categories} category={category} onCategory={setCategory} title={actionTitle} onTitle={setActionTitle} tc={generatedTc} onTc={setGeneratedTc} plan={operationPlan} onPlan={setOperationPlan} people={people.filter(p=>p.assignedBase===item.base)} assigned={assigned} onAssigned={setAssigned}/>{onOpenTools ? <button type="button" onClick={onOpenTools} className="flex items-center gap-2 rounded-lg border border-[#1268d8] px-3 py-2 text-xs font-bold text-[#1268d8]"><Wrench size={14} />Acessar Ferramentaria</button> : null}<MediaPicker documents files={actionFiles} onChange={setActionFiles} disabled={saving}/><button disabled={!actionTitle.trim() || saving} onClick={() => void submitGeneratedAction()} className="rounded-lg bg-[#1268d8] px-3 py-2 text-xs font-bold text-white disabled:opacity-40">{saving ? "Salvando…" : "Criar ação pendente"}</button></section> : null}<section className="space-y-2"><h4 className="font-bold">Linha do tempo {item.links.length ? "compartilhada" : ""}</h4>{combinedEntries.map((entry) => <article key={`${entry.origin}-${entry.id}`} className="rounded-xl border bg-white p-3"><div className="flex items-start justify-between gap-2"><div><b className="text-sm">{entry.kind === "action" ? "Ação executada" : entry.kind === "comment" ? "Comentário" : entry.kind === "link" ? "Vínculo" : entry.kind === "assignment" ? "Designação" : "Situação"}</b>{entry.origin !== "Registro atual" ? <p className="text-[10px] font-bold text-[#1769e0]">{entry.origin}</p> : null}</div>{entry.result ? <span className={`rounded-full px-2 py-1 text-[10px] font-bold ${entry.result === "satisfactory" ? "bg-green-50 text-green-700" : "bg-red-50 text-red-700"}`}>{entry.result === "satisfactory" ? "OK" : "Não OK"}</span> : null}</div><p className="mt-1 whitespace-pre-wrap text-sm">{entry.description}</p><MediaGallery items={entry.attachments} supabase={supabase}/>{entry.kind === "assignment" ? <p className="mt-2 text-xs font-bold text-[#52677f]">Executante: {entry.assignedTo?.length ? entry.assignedTo.map(id => `${userDirectory[id]?.name || "Mat."} · ${id}`).join(", ") : "Ainda não designado"}</p> : null}{entry.wallPostId ? <TaskExecutionHistory supabase={supabase} postId={entry.wallPostId} user={user} leadership={leadership} canExecute={canExecute} requireSignature={requireSignature} onError={onError} /> : null}<div className="mt-2 flex items-center gap-2 text-[10px] text-[#718197]"><UserAvatar employeeNumber={entry.employeeNumber} directory={userDirectory} size="xs" /><span>{userDirectory[entry.employeeNumber]?.name || `Mat. ${entry.employeeNumber}`} · {dateTime(entry.at)}</span></div></article>)}{!combinedEntries.length ? <p className="text-sm text-[#718197]">Nenhuma ação registrada.</p> : null}</section><section className="rounded-xl border border-[#dce6f0] p-3"><h4 className="font-bold">Registrar execução</h4><AssistantForm client={supabase} user={user} disabled={saving} form={{id:`execution-draft:${item.id}`,label:`Registrar execução · ${item.prefix}`,mode:'draft',fields:{description:{label:'Somente o que já foi executado e informado pelo usuário, sem inventar resultado',value:description,maxLength:12000},result:{label:'Resultado explicitamente informado: satisfactory = satisfatório; nonconforming = não conforme',value:result,options:['satisfactory','nonconforming']}}}} onApply={values=>{if(values.description!==undefined)setDescription(values.description);if(values.result!==undefined)setResult(values.result as 'satisfactory'|'nonconforming');}}/><p className="mt-1 text-xs text-[#718197]">Registre aqui somente o que já foi realizado. A liderança ou o inspetor pode solicitar o próximo giro ou serviço em GERAR AÇÃO.</p><textarea rows={3} value={description} onChange={(e) => setDescription(e.target.value)} placeholder="Descreva exatamente o que foi executado…" className="mt-2 w-full rounded-xl border p-3" /><MediaPicker documents files={executionFiles} onChange={setExecutionFiles} disabled={saving}/><div className="mt-2 flex flex-wrap gap-2"><select value={result} onChange={(e) => setResult(e.target.value as typeof result)} className="rounded-lg border px-2"><option value="satisfactory">OK / satisfatório</option><option value="nonconforming">Não OK / não satisfatório</option></select><button disabled={!description.trim() || saving} onClick={() => void addExecution()} className="rounded-lg bg-[#1268d8] px-3 py-2 text-xs font-bold text-white disabled:opacity-40">{saving ? "Salvando…" : "Registrar execução"}</button></div></section><section className="rounded-xl border border-[#dce6f0] p-3"><h4 className="font-bold">Comentários anteriores</h4><p className="mt-1 text-xs text-[#718197]">Observações e dicas não alteram o resultado técnico.</p><CommentSummary comments={combinedComments.map(c=>({id:c.id,employeeNumber:c.employeeNumber,at:c.at,body:c.description}))} directory={userDirectory} designator={taskDesignator(item.entries)} pinnedId={item.pinnedCommentId} newCount={combinedComments.filter(c=>c.employeeNumber!==user&&(!commentSeen||Date.parse(c.at)>Date.parse(commentSeen))).length} onOpen={()=>void seeComments()}/><details open={startWithComments||undefined} id={`record-comments-${item.id}`} onToggle={e=>{if(e.currentTarget.open)void seeComments();}} className="mt-2 rounded-lg bg-[#f4f7fb] p-2"><summary className="flex cursor-pointer items-center gap-2 text-xs font-bold"><MessageCircle size={14} />Comentários ({combinedComments.length})</summary><div className="mt-2 space-y-2">{combinedComments.map((entry) => <article key={`${entry.origin}-${entry.id}`} className="rounded-lg bg-white p-2"><p className="whitespace-pre-wrap text-sm">{entry.description}</p><MediaGallery items={entry.attachments} supabase={supabase}/>{leadership&&entry.origin==="Registro atual"?<button onClick={async()=>{if(!supabase)return;const{error}=await supabase.rpc("pin_technical_comment",{p_record_id:item.id,p_comment_id:item.pinnedCommentId===entry.id?null:entry.id});if(error)onError(error.message);}} className="mt-2 text-xs font-bold text-blue-700">{item.pinnedCommentId===entry.id?"Desafixar orientação":"Fixar orientação"}</button>:null}<div className="mt-2 flex items-center gap-2 text-[10px] text-[#718197]"><UserAvatar employeeNumber={entry.employeeNumber} directory={userDirectory} size="xs" /><span>{userDirectory[entry.employeeNumber]?.name || `Mat. ${entry.employeeNumber}`} · {dateTime(entry.at)}{entry.origin !== "Registro atual" ? ` · ${entry.origin}` : ""}</span></div></article>)}{!combinedComments.length ? <p className="text-xs text-[#718197]">Nenhum comentário.</p> : null}</div></details><p className="mt-3 text-xs text-slate-600">Comentários técnicos ficam vinculados ao caso, com autoria e auditoria. Conversas particulares continuam restritas aos participantes.</p><details className="my-3 rounded-lg border p-3"><summary className="cursor-pointer font-bold">Adicionar Comentário Técnico</summary><AssistantForm client={supabase} user={user} disabled={saving} form={{id:`comment-draft:${item.id}`,label:`Comentário técnico · ${item.prefix}`,mode:'draft',fields:{comment:{label:'Comentário técnico, sem transformar opinião em execução ou aprovação',value:comment,maxLength:12000}}}} onApply={values=>{if(values.comment!==undefined)setComment(values.comment);}}/><textarea aria-label="Comentário Técnico" className="mt-2 w-full rounded-lg border p-3" rows={3} value={comment} onChange={e=>setComment(e.target.value)}/><MediaPicker documents files={commentFiles} onChange={setCommentFiles} disabled={saving}/><button disabled={saving||(!comment.trim()&&!commentFiles.length)} onClick={()=>void requireSignature(()=>addComment(),"Confirmar comentário técnico")} className="rounded-lg bg-blue-700 px-3 py-2 text-white disabled:opacity-40">Confirmar comentário</button></details><button onClick={()=>requestRecordChat(item.id)} className="mt-2 rounded-lg bg-emerald-700 px-3 py-2 text-xs font-bold text-white">Abrir conversa</button></section></div></Dialog>
    ;
}

function Dialog({ title, onClose, children, wide, assistantWide }: { title: string; onClose: () => void; children: React.ReactNode; wide?: boolean; assistantWide?:boolean; }) { return <ModalLayer><div className="fixed inset-0 z-[80] grid place-items-end bg-[#071a30]/60 backdrop-blur-sm sm:place-items-center sm:p-4" onMouseDown={(e) => { if(e.target === e.currentTarget) onClose(); }}><div role="dialog" aria-modal="true" className={`max-h-[92dvh] w-full overflow-auto rounded-t-2xl bg-white shadow-2xl sm:rounded-2xl ${assistantWide ? "sm:max-w-6xl" : wide ? "sm:max-w-3xl" : "sm:max-w-xl"}`}><header className="sticky top-0 z-10 flex items-center justify-between border-b bg-white p-4"><h2 className="text-lg font-bold">{title}</h2><div className="flex items-center gap-2"><button onClick={onClose} aria-label="Fechar"><X size={20} /></button></div></header><div className="p-4">{children}</div></div></div></ModalLayer>; }
function Field({ label, children }: { label: string; children: React.ReactNode; }) { return <label className="block"><span className="mb-1 block text-xs font-bold text-[#52677f]">{label}</span><div className="[&>input]:h-11 [&>input]:w-full [&>input]:rounded-xl [&>input]:border [&>input]:px-3 [&>select]:h-11 [&>select]:w-full [&>select]:rounded-xl [&>select]:border [&>select]:bg-white [&>select]:px-3 [&>textarea]:w-full [&>textarea]:rounded-xl [&>textarea]:border [&>textarea]:p-3">{children}</div></label>; }

type TechnicalTask = {title:string;status:string;editedAt?:string;editedBy?:string;executions:{id:string;employeeNumber:string;at:string;description:string;result:string;attachments?:RecordMedia[]}[]};
function TaskExecutionHistory({supabase,postId,user,leadership,canExecute,requireSignature,onError}:{supabase:SupabaseClient|null;postId:string;user:string;leadership:boolean;canExecute:boolean;requireSignature:(action:()=>void|Promise<void>,label?:string)=>Promise<boolean>;onError:(message:string)=>void}) {
 const [task,setTask]=useState<TechnicalTask|null>(null);
 const [files,setFiles]=useState<File[]>([]);
 const resultRequest=useRef<string|null>(null);const [resultText,setResultText]=useState("");const [result,setResult]=useState("satisfactory");const [resultError,setResultError]=useState("");const [resultOpen,setResultOpen]=useState(false);
 const [revision,setRevision]=useState(0);const [author,setAuthor]=useState("");const [editing,setEditing]=useState(false);const [text,setText]=useState("");const [saving,setSaving]=useState(false);const [editRevision,setEditRevision]=useState(0);
 useEffect(()=>{if(!supabase)return;let active=true;let firstLoad=true;const load=async()=>{const {data,error}=await supabase.from("operational_wall_posts").select("data,revision").eq("id",postId).maybeSingle();if(error){onError(`Histórico da tarefa indisponível: ${error.message}`);return;}if(active){setTask(data?.data?.actions?.[0]??null);setRevision(data?.revision??0);setAuthor(data?.data?.createdBy??"");if(firstLoad){firstLoad=false;const editedAt=data?.data?.actions?.[0]?.editedAt;if(editedAt){const{error:readError}=await supabase.rpc("mark_maintenance_edit_read",{p_post_id:postId,p_edited_at:editedAt});if(readError)onError(readError.message);else window.dispatchEvent(new Event("maintenance-edit-read"));}}}};void load();const channel=supabase.channel(`technical-task-${postId}`).on("postgres_changes",{event:"*",schema:"public",table:"operational_wall_posts",filter:`id=eq.${postId}`},()=>void load()).subscribe();return()=>{active=false;void supabase.removeChannel(channel);};},[supabase,postId,onError]);
 async function save(){if(!supabase||!text.trim()||saving)return;setSaving(true);try{await requireSignature(async()=>{const {data,error}=await supabase.rpc("edit_maintenance_action",{p_post_id:postId,p_title:text.trim(),p_expected_revision:editRevision});if(error){onError(`Edição não salva: ${error.message}`);return;}setTask(data.data.actions[0]);setRevision(data.revision);setEditing(false);},"Confirmar correção da ação");}finally{setSaving(false);}}
 async function saveResult(){if(!supabase||saving||!resultText.trim())return;setSaving(true);setResultError("");try{await requireSignature(async()=>{const attachments=await uploadRecordMedia(supabase,files,`wall/${postId}`,user);const{error}=await supabase.rpc("record_maintenance_task_result",{p_attachments:attachments,p_post_id:postId,p_description:resultText,p_result:result,p_request_id:resultRequest.current??(resultRequest.current=crypto.randomUUID())});if(error){setResultError(error.message);return;}const{data}=await supabase.from("operational_wall_posts").select("data,revision").eq("id",postId).maybeSingle();if(data){setTask(data.data.actions[0]);setRevision(data.revision);}resultRequest.current=null;setResultText("");setFiles([]);setResultOpen(false);},"Assinar resultado desta tarefa");}catch(err){setResultError((err as Error).message);}finally{setSaving(false);}}
 if(!task)return null;
 const labels:Record<string,string>={pending:"Pendente",acknowledged:"Ciente",in_progress:"Em execução",satisfactory:"Satisfatório",nonconforming:"Não conforme",resolved:"Encerrada"};
 return <div className={`mt-3 space-y-2 border-l-2 pl-3 ${task.status==="satisfactory"?"border-green-400":task.status==="nonconforming"?"border-red-400":"border-blue-200"}`}><b className="text-xs">Tarefa: {labels[task.status]||task.status}</b><p className="whitespace-pre-wrap text-sm font-semibold">{task.title}</p>{task.editedAt?<p className="text-xs font-bold text-[#60758c]">Alterada por mat. {task.editedBy} · {dateTime(task.editedAt)}</p>:null}{leadership&&author===user&&!editing?<button className="rounded-lg border border-blue-200 px-3 py-2 text-xs font-bold text-blue-800" onClick={()=>{setText(task.title);setEditRevision(revision);setEditing(true);}}>Editar finalidade da ação</button>:null}{editing?<div className="space-y-2"><label className="block text-xs font-bold">Finalidade do giro ou procedimento e referência do flight check<textarea className="mt-2 w-full rounded-xl border bg-white p-3 text-sm font-normal" rows={5} value={text} onChange={e=>setText(e.target.value)}/></label><p className="text-xs text-amber-800">A correção será registrada no histórico e destacada em amarelo para os destinatários.</p><div className="flex gap-2"><button disabled={saving||!text.trim()} onClick={()=>void save()} className="rounded-lg bg-blue-600 px-3 py-2 text-xs font-bold text-white disabled:opacity-50">{saving?"Salvando…":"Salvar correção"}</button><button disabled={saving} onClick={()=>setEditing(false)} className="rounded-lg border px-3 py-2 text-xs">Cancelar</button></div></div>:null}{canExecute?<button onClick={()=>setResultOpen(!resultOpen)} className="rounded-lg bg-blue-600 px-3 py-2 text-xs font-bold text-white">Registrar resultado desta tarefa</button>:null}{resultOpen?<div className="space-y-2 rounded-xl border bg-white p-3"><p className="text-xs font-bold">Resultado vinculado a: {task.title}</p><textarea aria-label="Resultado desta tarefa" value={resultText} onChange={e=>setResultText(e.target.value)} rows={3} className="w-full rounded-lg border p-2"/><MediaPicker documents files={files} onChange={setFiles} disabled={saving}/><select aria-label="Avaliação da tarefa" value={result} onChange={e=>setResult(e.target.value)} className="h-10 rounded-lg border"><option value="satisfactory">Satisfatório</option><option value="nonconforming">Não satisfatório</option></select><button disabled={saving||!resultText.trim()} onClick={()=>void saveResult()} className="ml-2 rounded-lg bg-green-700 px-3 py-2 text-xs font-bold text-white disabled:opacity-40">Assinar resultado</button>{resultError?<p role="alert" className="text-sm text-red-700">{resultError}</p>:null}</div>:null}{task.executions.map(execution=><div key={execution.id} className="rounded-lg bg-[#f4f7fb] p-3"><p className="text-sm">{execution.description}</p><MediaGallery items={execution.attachments} supabase={supabase}/><p className="mt-1 text-xs">{execution.result==="satisfactory"?"Satisfatório":"Não conforme"} · Mat. {execution.employeeNumber} · {dateTime(execution.at)}</p></div>)}</div>;
}
